struct List {
    elm: Int,
    next: Option<Box<List>>,
}

fn get(lst: Box<List>, pos: Int) -> Option<Int> {
    if lst.elm == pos {
        Some(lst.elm)
    } else {
        match lst.next {
            Some(n) => get(n, pos),
            None => None,
        }
    }
}

